import React from 'react';
import { Box, Typography, IconButton, Stack, Paper } from '@mui/material';
import {
  Savings,
  AccountBalanceWallet,
  Payment,
  History,
  AddCircleOutline,
  MoreHoriz,
  Person,
  PersonOutline,
  ContactsOutlined,
  SettingsOutlined,
} from '@mui/icons-material';
import { Link, useNavigate } from 'react-router-dom';

const menuItems = [
  { label: 'เงินดาวน์', path: 'downPayment', icon: <Savings /> },
  { label: 'สินเชื่อ', path: 'loan', icon: <AccountBalanceWallet /> },
  { label: 'ชำระเงิน', path: 'paid', icon: <Payment /> },
  { label: 'ประวัติ', path: 'paidHistory', icon: <History /> },
  { label: 'สินเชื่อใหม่', path: 'newLoan', icon: <AddCircleOutline /> },
  { label: 'ตั้งค่า', path: 'settup', icon: <SettingsOutlined /> },
  { label: 'ติดต่อ', path: 'contact', icon: <ContactsOutlined /> },
  { label: 'ข้อมูลส่วนตัว', path: 'userInfo', icon: <PersonOutline /> },
];

const HomeMenu = () => {

  const navigate = useNavigate();
  return (
    <Box p={3} >
      <Stack direction="row" flexWrap="wrap" spacing={2} useFlexGap justifyContent={'center'} >
        {menuItems.map((item, index) => (
          <Link key={item.path} to={item.path}>
            <Paper
              key={index}
              elevation={1}
              sx={{
                width: '120px',
                height: '120px',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                background: 'linear-gradient(135deg, #c50cd6ff 0%, #b915b1ff 50%, #d80adfff 100%)',
                '&:hover': {
                  background: 'linear-gradient(135deg, #266955ff 0%, #125f4cff 50%, #0e8d78ff 100%)',
                  cursor: 'pointer',
                },
              }}
            >
              <IconButton color='info'>{item.icon}</IconButton>
              <Typography variant="body2" mt={1} color='info'>
                {item.label}
              </Typography>
            </Paper>
          </Link>
        ))}
      </Stack>
    </Box>
  );
};

export default HomeMenu;
